package com.eurobuddha.atomix;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit interrupted-write explanations only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-atomix-recovery.py from localization/atomix-recovery-messages.json. */
public final class RecoveryMessages {
    private RecoveryMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "A node write lost its reply and may have completed.": return Language.msg(l10n_atomix_recovery_unknown);
            case "A node write": return Language.msg(l10n_atomix_recovery_write);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("((?s:.*))\\ got\\ no\\ reply\\ within\\ the\\ 3\\ minute\\ limit\\.\\ The\\ node\\ may\\ have\\ been\\ restarting\\ or\\ stalled;\\ it\\ may\\ still\\ have\\ completed\\."),
        java.util.regex.Pattern.compile("((?s:.*))\\ came\\ back\\ without\\ a\\ usable\\ result,\\ so\\ whether\\ it\\ completed\\ is\\ unknown\\.\\ The\\ node\\ answered,\\ so\\ restarting\\ it\\ will\\ not\\ help\\."),
        java.util.regex.Pattern.compile("((?s:.*))\\ replied,\\ but\\ AtomiX\\ failed\\ while\\ handling\\ the\\ reply\\.\\ The\\ command\\ most\\ likely\\ completed\\ on\\ the\\ node\\."),
        java.util.regex.Pattern.compile("((?s:.*))\\ was\\ started\\ and\\ AtomiX\\ stopped\\ before\\ the\\ reply\\ was\\ handled\\ \\-\\ most\\ likely\\ the\\ app\\ was\\ killed\\ in\\ the\\ background\\.\\ Nothing\\ was\\ recorded\\ either\\ way,\\ and\\ the\\ node\\ was\\ never\\ at\\ fault\\."),
        java.util.regex.Pattern.compile("((?s:.*))\\ about\\ (-?[0-9]+)\\ min\\ ago"),
        java.util.regex.Pattern.compile("A\\ '((?s:.*))'\\ command")
    };
    private static final int[] RESOURCES={l10n_atomix_recovery_timeout,l10n_atomix_recovery_incomplete,l10n_atomix_recovery_callback,l10n_atomix_recovery_stopped,l10n_atomix_recovery_ago,l10n_atomix_recovery_command};
    private static final boolean[][] DIAGNOSTIC={{true},{true},{true},{true},{true,false},{false}};
}
